// Applies pending SQL migrations from database/migrations (generated by drizzle-kit from models/schema.ts).
import { connect, disconnect, migrateDb } from '../config/db.ts';

const conn = await connect();
await migrateDb();
console.log(`Migrations applied (${conn.driver === 'pg' ? 'PostgreSQL' : 'PGlite'}).`);
await disconnect();
